package com.xato.record;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.provider.Settings;import android.widget.*;import android.view.*;import java.io.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences prefs; LinearLayout root; Switch mic; boolean requestedMic;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("settings",0);render();}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setPadding(0,dp(12),0,dp(8));root.addView(t);return t;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);root.addView(b,new LinearLayout.LayoutParams(-1,dp(56)));b.setOnClickListener(v->r.run());}
 void select(String title,String key,String[] values,int def){label(title,14);Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));sp.setSelection(prefs.getInt(key,def));root.addView(sp);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long id){prefs.edit().putInt(key,pos).apply();}});}
 void render(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(24),dp(24),dp(32));root.setBackgroundColor(Color.rgb(16,18,24));scroll.addView(root);setContentView(scroll);
 label("XatoRecord",34);label("PANTALLA  /  EDICIÓN LIGERA",12).setTextColor(Color.rgb(255,64,92));label("Captura lo que importa.",24);label("Vídeo MP4 · Sin anuncios · Guardado local",14);
 button("●  Iniciar grabación",()->begin());button("Pausar / reanudar",()->command("PAUSE"));button("■  Detener y guardar",()->command("STOP"));
 label("Calidad de grabación",22);select("Resolución máxima (lado corto)","quality",new String[]{"480p · Ahorro","720p · Equilibrada","1080p · Alta calidad"},1);select("Fotogramas por segundo","fps",new String[]{"24 FPS","30 FPS","60 FPS"},1);select("Tasa de vídeo","bitrate",new String[]{"2 Mbps","4 Mbps","8 Mbps","12 Mbps"},1);
 mic=new Switch(this);mic.setText("Grabar micrófono");mic.setChecked(prefs.getBoolean("mic",false));root.addView(mic);mic.setOnCheckedChangeListener((v,c)->prefs.edit().putBoolean("mic",c).apply());
 label("Tu botón flotante",22);label("Arrastra para mover. Toca para abrir pausa y detener. La imagen puede aparecer en el vídeo.",14);
 button("Permitir botón sobre otras apps",()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));
 button("Elegir imagen del botón",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,20);});button("Restaurar icono Xato",()->{new File(getFilesDir(),"bubble.png").delete();Toast.makeText(this,"Se aplicará al iniciar otra grabación",0).show();});
 select("Tamaño del botón","size",new String[]{"40 dp","52 dp","64 dp"},1);select("Opacidad del botón","alpha",new String[]{"50 %","75 %","100 %"},2);
 label("Tus grabaciones",22);button("Abrir vídeos guardados",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI));}catch(Exception e){Toast.makeText(this,"Abre Galería → Movies/XatoRecord",1).show();}});
 label("Guardado en Movies/XatoRecord. La orientación queda fijada al iniciar. Algunas apps protegen su contenido. Esta versión graba micrófono o vídeo sin audio; no incluye audio interno ni editor.",13);
 }
 void command(String a){if(!RecordService.running){Toast.makeText(this,"No hay grabación activa",0).show();return;}startService(new Intent(this,RecordService.class).setAction(a));}
 void begin(){if(RecordService.running){Toast.makeText(this,"Ya hay una grabación activa",0).show();return;}requestedMic=mic.isChecked();if(requestedMic&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},30);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},31);return;}capture();}
 void capture(){startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(),10);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==30){if(g.length>0&&g[0]==0)begin();else Toast.makeText(this,"Desactiva micrófono o concede el permiso",1).show();}if(r==31)capture();}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==10&&result==RESULT_OK&&data!=null){startForegroundService(new Intent(this,RecordService.class).setAction("START").putExtra("data",data).putExtra("mic",requestedMic));}if(req==20&&result==RESULT_OK&&data!=null){try{android.graphics.ImageDecoder.Source src=android.graphics.ImageDecoder.createSource(getContentResolver(),data.getData());android.graphics.Bitmap b=android.graphics.ImageDecoder.decodeBitmap(src,(decoder,info,source)->decoder.setTargetSize(192,192));try(FileOutputStream out=new FileOutputStream(new File(getFilesDir(),"bubble.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();Toast.makeText(this,"Imagen lista para la próxima grabación",0).show();}catch(Exception e){Toast.makeText(this,"No se pudo leer la imagen",1).show();}}}
}